function mk(day, theme, cue, vids, blocks) {
  return {
    id: "d-" + day.toLowerCase(),
    name: day,
    theme,
    cue,
    videoIds: vids,
    blocks: blocks.map((b, i) => ({ id: `${day.toLowerCase()}-${i}`, title: b[0], minutes: b[1], text: b[2] })),
  };
}

